(function() {
	// src/Modules/CrestApps.OrchardCore.Learning.Assessments/Assets/js/quiz-question-order-helpers.js
	/**
	* Keeps the order set for the questions still chosen and adds the new ones last.
	* @param {string[] | null | undefined} order The order set so far.
	* @param {string[] | null | undefined} chosen The questions chosen now, in the picker's order.
	* @returns {string[]}
	*/
	function mergeOrder(order, chosen) {
		const selected = new Set(chosen ?? []);
		const kept = (order ?? []).filter((id) => selected.has(id));
		const known = new Set(kept);
		return [...kept, ...(chosen ?? []).filter((id) => !known.has(id))];
	}
	/**
	* Moves a question up (delta -1) or down (delta 1); a move past either end changes nothing.
	* @param {string[]} order The order.
	* @param {number} index The position of the question.
	* @param {number} delta The move.
	* @returns {string[]}
	*/
	function move(order, index, delta) {
		const target = index + delta;
		const result = [...order];
		if (index < 0 || index >= result.length || target < 0 || target >= result.length) return result;
		[result[index], result[target]] = [result[target], result[index]];
		return result;
	}
	// src/Modules/CrestApps.OrchardCore.Learning.Assessments/Assets/js/quiz-question-order.js
	function chosen(select) {
		return [...select.options].filter((option) => option.selected && option.value).map((option) => option.value);
	}
	function apply(select, order) {
		const byValue = new Map([...select.options].map((option) => [option.value, option]));
		let anchor = null;
		for (const id of order) {
			const option = byValue.get(id);
			if (!option) continue;
			if (anchor) anchor.after(option);
			else select.prepend(option);
			anchor = option;
		}
		if (window.Selectpicker) window.Selectpicker.getOrCreateInstance(select)?.refresh();
	}
	function init(root) {
		const select = document.getElementById(root.dataset.select);
		const list = root.querySelector("[data-question-order-list]");
		const empty = root.querySelector("[data-question-order-empty]");
		const template = root.querySelector("[data-question-order-template]");
		if (!select || !list || !template) return;
		let order = chosen(select);
		const render = () => {
			list.replaceChildren();
			order.forEach((id, index) => {
				const row = template.content.firstElementChild.cloneNode(true);
				const option = [...select.options].find((candidate) => candidate.value === id);
				row.querySelector("[data-question-order-title]").textContent = `${index + 1}. ${option?.textContent?.trim() ?? id}`;
				const up = row.querySelector("[data-question-order-up]");
				const down = row.querySelector("[data-question-order-down]");
				up.disabled = index === 0;
				down.disabled = index === order.length - 1;
				up.addEventListener("click", () => update(move(order, index, -1), index - 1, "up"));
				down.addEventListener("click", () => update(move(order, index, 1), index + 1, "down"));
				list.append(row);
			});
			if (empty) empty.hidden = order.length > 0;
		};
		const update = (next, focusIndex, button) => {
			order = next;
			apply(select, order);
			render();
			const row = list.children[focusIndex];
			const target = row?.querySelector(`[data-question-order-${button}]`);
			(target && !target.disabled ? target : row?.querySelector("button:not([disabled])"))?.focus();
		};
		select.addEventListener("changed.bs.select", () => {
			order = mergeOrder(order, chosen(select));
			apply(select, order);
			render();
		});
		select.addEventListener("change", () => {
			order = mergeOrder(order, chosen(select));
			render();
		});
		render();
	}
	document.addEventListener("DOMContentLoaded", () => {
		document.querySelectorAll("[data-question-order]").forEach(init);
	});
})();
